import{_ as e,c as r,o as t,ag as i}from"./chunks/framework.CMajxlqO.js";const c=JSON.parse('{"title":"Spara och arkivera projekt","description":"","frontmatter":{},"headers":[],"relativePath":"10-projekthantering/spara-arkivera.md","filePath":"10-projekthantering/spara-arkivera.md","lastUpdated":1768470380000}'),n={name:"10-projekthantering/spara-arkivera.md"};function s(l,a,o,p,d,k){return t(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="spara-och-arkivera-projekt" tabindex="-1">Spara och arkivera projekt <a class="header-anchor" href="#spara-och-arkivera-projekt" aria-label="Permalink to &quot;Spara och arkivera projekt&quot;">​</a></h1><p>Korrekt hantering av TIA Portal-projekt är avgörande för att säkerställa att ditt arbete inte går förlorat och att du kan återskapa system vid behov.</p><h2 id="spara-projekt" tabindex="-1">Spara projekt <a class="header-anchor" href="#spara-projekt" aria-label="Permalink to &quot;Spara projekt&quot;">​</a></h2><h3 id="grundlaggande-sparning" tabindex="-1">Grundläggande sparning <a class="header-anchor" href="#grundlaggande-sparning" aria-label="Permalink to &quot;Grundläggande sparning&quot;">​</a></h3><ul><li><strong>Ctrl+S</strong> - Spara projektet</li><li><strong>Project &gt; Save</strong> - Samma funktion via menyn</li><li>Autosave kan konfigureras i inställningar</li></ul><h3 id="var-sparas-projektet" tabindex="-1">Var sparas projektet? <a class="header-anchor" href="#var-sparas-projektet" aria-label="Permalink to &quot;Var sparas projektet?&quot;">​</a></h3><p>TIA Portal-projekt sparas som mappar med filändelsen <code>.ap18</code> (för V18):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MittProjekt_V18/</span></span>
<span class="line"><span>├── MittProjekt.ap18</span></span>
<span class="line"><span>├── AdditionalFiles/</span></span>
<span class="line"><span>├── UserFiles/</span></span>
<span class="line"><span>└── [diverse systemfiler]</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Spara ofta! TIA Portal kan krascha vid stora projekt. Aktivera autosave under <strong>Options &gt; Settings &gt; General &gt; Auto save</strong>.</p></div><h2 id="arkivera-projekt" tabindex="-1">Arkivera projekt <a class="header-anchor" href="#arkivera-projekt" aria-label="Permalink to &quot;Arkivera projekt&quot;">​</a></h2><p>Arkivering skapar en komprimerad fil som innehåller allt för att återskapa projektet.</p><h3 id="skapa-arkiv" tabindex="-1">Skapa arkiv <a class="header-anchor" href="#skapa-arkiv" aria-label="Permalink to &quot;Skapa arkiv&quot;">​</a></h3><ol><li>Gå till <strong>Project &gt; Archive...</strong></li><li>Välj var arkivfilen ska sparas</li><li>Ange filnamn (t.ex. <code>MittProjekt_2024-01-15</code>)</li><li>Klicka <strong>Archive</strong></li></ol><h3 id="arkiveringsalternativ" tabindex="-1">Arkiveringsalternativ <a class="header-anchor" href="#arkiveringsalternativ" aria-label="Permalink to &quot;Arkiveringsalternativ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Alternativ</th><th>Beskrivning</th></tr></thead><tbody><tr><td>Include subprojects</td><td>Inkludera länkade delprojekt</td></tr><tr><td>Include password-protected data</td><td>Behåll krypterade block</td></tr><tr><td>Compress archive</td><td>Minska filstorlek (rekommenderas)</td></tr></tbody></table><h3 id="arkivformat" tabindex="-1">Arkivformat <a class="header-anchor" href="#arkivformat" aria-label="Permalink to &quot;Arkivformat&quot;">​</a></h3><p>Arkivfilen får filändelsen:</p><ul><li><code>.zap18</code> - Komprimerat arkiv (V18)</li><li><code>.ap18</code> - Okomprimerat (vanligt projekt)</li></ul><h2 id="retrieve-aterskapa-projekt" tabindex="-1">Retrieve (Återskapa) projekt <a class="header-anchor" href="#retrieve-aterskapa-projekt" aria-label="Permalink to &quot;Retrieve (Återskapa) projekt&quot;">​</a></h2><h3 id="oppna-arkiverat-projekt" tabindex="-1">Öppna arkiverat projekt <a class="header-anchor" href="#oppna-arkiverat-projekt" aria-label="Permalink to &quot;Öppna arkiverat projekt&quot;">​</a></h3><ol><li>Gå till <strong>Project &gt; Retrieve...</strong></li><li>Välj arkivfilen (<code>.zap18</code>)</li><li>Ange var projektet ska extraheras</li><li>Klicka <strong>Retrieve</strong></li></ol><h3 id="automatisk-extrahering" tabindex="-1">Automatisk extrahering <a class="header-anchor" href="#automatisk-extrahering" aria-label="Permalink to &quot;Automatisk extrahering&quot;">​</a></h3><p>TIA Portal extraherar arkivet och öppnar projektet automatiskt.</p><h2 id="projektbibliotek" tabindex="-1">Projektbibliotek <a class="header-anchor" href="#projektbibliotek" aria-label="Permalink to &quot;Projektbibliotek&quot;">​</a></h2><p>Spara återanvändbara delar i ett bibliotek:</p><h3 id="global-library" tabindex="-1">Global Library <a class="header-anchor" href="#global-library" aria-label="Permalink to &quot;Global Library&quot;">​</a></h3><ol><li>Öppna <strong>Libraries</strong> i sidopanelen</li><li>Högerklicka i <strong>Global libraries</strong></li><li>Välj <strong>Create new global library</strong></li><li>Dra block/taggar/typer till biblioteket</li></ol><h3 id="vad-kan-sparas-i-bibliotek" tabindex="-1">Vad kan sparas i bibliotek? <a class="header-anchor" href="#vad-kan-sparas-i-bibliotek" aria-label="Permalink to &quot;Vad kan sparas i bibliotek?&quot;">​</a></h3><ul><li>Programblock (FB, FC, DB)</li><li>PLC-datatyper (UDT)</li><li>HMI-skärmbilder och objekt</li><li>Taggtabeller</li><li>Hårdvarukonfigurationer</li></ul><h3 id="anvand-bibliotekselement" tabindex="-1">Använd bibliotekselement <a class="header-anchor" href="#anvand-bibliotekselement" aria-label="Permalink to &quot;Använd bibliotekselement&quot;">​</a></h3><ol><li>Öppna biblioteket</li><li>Dra elementet till ditt projekt</li><li>Elementet kopieras (inte länkas)</li></ol><h2 id="migrera-projekt-mellan-versioner" tabindex="-1">Migrera projekt mellan versioner <a class="header-anchor" href="#migrera-projekt-mellan-versioner" aria-label="Permalink to &quot;Migrera projekt mellan versioner&quot;">​</a></h2><h3 id="uppgradera-projekt" tabindex="-1">Uppgradera projekt <a class="header-anchor" href="#uppgradera-projekt" aria-label="Permalink to &quot;Uppgradera projekt&quot;">​</a></h3><p>TIA Portal kan öppna projekt från äldre versioner:</p><ol><li>Öppna äldre projekt</li><li>TIA Portal frågar om uppgradering</li><li>Projektet konverteras till ny version</li></ol><div class="warning custom-block"><p class="custom-block-title">Obs</p><p>Uppgradering är permanent - spara en kopia av originalprojektet först!</p></div><h3 id="kompatibilitet" tabindex="-1">Kompatibilitet <a class="header-anchor" href="#kompatibilitet" aria-label="Permalink to &quot;Kompatibilitet&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Från version</th><th>Till V18</th></tr></thead><tbody><tr><td>V17</td><td>✓ Direkt uppgradering</td></tr><tr><td>V16</td><td>✓ Direkt uppgradering</td></tr><tr><td>V15</td><td>✓ Kräver mellansteg</td></tr><tr><td>V14 och äldre</td><td>✓ Stegvis via äldre versioner</td></tr></tbody></table><h2 id="best-practices-for-projekthantering" tabindex="-1">Best practices för projekthantering <a class="header-anchor" href="#best-practices-for-projekthantering" aria-label="Permalink to &quot;Best practices för projekthantering&quot;">​</a></h2><h3 id="namngivning" tabindex="-1">Namngivning <a class="header-anchor" href="#namngivning" aria-label="Permalink to &quot;Namngivning&quot;">​</a></h3><p>Använd konsekvent namngivning:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Kundnamn]_[Maskin]_[Version]_[Datum]</span></span>
<span class="line"><span>Exempel: ABCIndustri_Transportband1_V2_20240115</span></span></code></pre></div><h3 id="mappstruktur" tabindex="-1">Mappstruktur <a class="header-anchor" href="#mappstruktur" aria-label="Permalink to &quot;Mappstruktur&quot;">​</a></h3><p>Organisera projekt på disk:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Projekt/</span></span>
<span class="line"><span>├── ABCIndustri/</span></span>
<span class="line"><span>│   ├── Aktiv/</span></span>
<span class="line"><span>│   │   └── Transportband1_V18/</span></span>
<span class="line"><span>│   ├── Arkiv/</span></span>
<span class="line"><span>│   │   ├── Transportband1_2024-01-10.zap18</span></span>
<span class="line"><span>│   │   └── Transportband1_2024-01-05.zap18</span></span>
<span class="line"><span>│   └── Bibliotek/</span></span>
<span class="line"><span>│       └── StandardBlock.al18</span></span>
<span class="line"><span>└── XYZFabrik/</span></span>
<span class="line"><span>    └── ...</span></span></code></pre></div><h3 id="versionsdokumentation" tabindex="-1">Versionsdokumentation <a class="header-anchor" href="#versionsdokumentation" aria-label="Permalink to &quot;Versionsdokumentation&quot;">​</a></h3><p>Skapa en versions-logg:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Version: 2.0</span></span>
<span class="line"><span>Datum: 2024-01-15</span></span>
<span class="line"><span>Ändringar:</span></span>
<span class="line"><span>- Lade till ny motorstyrning</span></span>
<span class="line"><span>- Fixade bugg i larmhantering</span></span>
<span class="line"><span>- Uppdaterade HMI-layout</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109817218/updates-for-step-7-v18-s7-plcsim-v18-and-wincc-v18" target="_blank" rel="noreferrer">TIA Portal Documentation Overview</a> - Uppdateringar och dokumentation</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><ul><li><a href="./backup-versioner.html">Backup och versioner</a> - Säkerhetskopiering</li><li><a href="./exportera-taggar.html">Exportera taggar</a> - Arbeta med Excel</li></ul>`,53)])])}const b=e(n,[["render",s]]);export{c as __pageData,b as default};
